{
  "version": 1,
  "title": "Meridian DAO Treasury Rebalancing Policy",
  "summary": "The treasury committee may rebalance between SOL Reserve (60% target) and Stable Reserve (40% target) when drift exceeds 10 percentage points, moving only the amount needed to restore target allocation, capped at 10% of total treasury value (100,000 PLAY), provided price data is current.",
  "parties": [
    {
      "id": "meridian_dao_treasury",
      "label": "Meridian DAO Treasury",
      "role": "funder"
    },
    {
      "id": "sol_reserve",
      "label": "SOL Reserve Account",
      "role": "recipient"
    },
    {
      "id": "stable_reserve",
      "label": "Stable Reserve Account",
      "role": "recipient"
    }
  ],
  "escrow": {
    "asset": "PLAY",
    "amount": 1000000,
    "funder": "meridian_dao_treasury"
  },
  "deadline": "2026-11-07T23:59:59Z",
  "evidenceSources": [
    {
      "id": "price_snapshot",
      "description": "Timestamp and SOL price data used for rebalancing decision",
      "kind": "data"
    },
    {
      "id": "treasury_snapshot",
      "description": "Current SOL Reserve and Stable Reserve balances and timestamp",
      "kind": "data"
    },
    {
      "id": "rebalance_proposal",
      "description": "Treasury committee proposal specifying target allocation percentages and rebalance amounts",
      "kind": "document"
    }
  ],
  "outcomes": [
    {
      "id": "no_rebalance",
      "description": "No rebalancing occurs; funds remain in current allocation",
      "payouts": []
    },
    {
      "id": "rebalance_to_sol",
      "description": "Move funds from Stable Reserve to SOL Reserve to restore target allocation",
      "payouts": [
        {
          "to": "sol_reserve",
          "variable": true,
          "max": 100000
        }
      ]
    },
    {
      "id": "rebalance_to_stable",
      "description": "Move funds from SOL Reserve to Stable Reserve to restore target allocation",
      "payouts": [
        {
          "to": "stable_reserve",
          "variable": true,
          "max": 100000
        }
      ]
    }
  ],
  "judgmentClauses": [
    {
      "id": "rebalance_decision",
      "question": "Should the treasury be rebalanced, and if so, in which direction and by how much?",
      "allowedOutcomes": [
        "no_rebalance",
        "rebalance_to_sol",
        "rebalance_to_stable"
      ],
      "guidance": "Determine current SOL Reserve and Stable Reserve percentages from treasury snapshot. If either percentage drifts more than 10 percentage points from target (SOL 60%, Stable 40%), calculate the amount needed to restore exact target allocation. If price snapshot is more than 24 hours older than treasury snapshot, return no_rebalance. If calculated rebalance amount exceeds 100,000 PLAY (10% of 1,000,000), cap the movement at 100,000 PLAY and return the appropriate direction. Otherwise, return the rebalance outcome with the calculated amount."
    }
  ],
  "hardLimits": {
    "maxTotalPayout": 100000,
    "maxSingleTransfer": 100000
  },
  "defaultOutcome": "no_rebalance"
}
```

